// NJW — arquivo único para hospedagem (Render etc.): extrai o jogo embutido, restaura/salva o progresso e inicia o servidor.
// Persistência opcional: defina UPSTASH_REDIS_REST_URL e UPSTASH_REDIS_REST_TOKEN (conta grátis em upstash.com).
'use strict';
const fs = require('fs'), path = require('path'), os = require('os'), zlib = require('zlib');
const DATA = "";
const root = path.join(os.tmpdir(), 'njw-app');
fs.rmSync(root, { recursive: true, force: true });
const tar = zlib.gunzipSync(Buffer.from(DATA, 'base64'));
for (let o = 0; o + 512 <= tar.length;) {
  const h = tar.subarray(o, o + 512); if (h.every(x => x === 0)) break;
  let name = h.toString('utf8', 0, 100).replace(/\0.*$/, ''); const pre = h.toString('utf8', 345, 500).replace(/\0.*$/, ''); if (pre) name = pre + '/' + name;
  const size = parseInt(h.toString('utf8', 124, 136).replace(/\0.*$/, '').trim() || '0', 8), type = String.fromCharCode(h[156]);
  o += 512; const body = tar.subarray(o, o + size); o += Math.ceil(size / 512) * 512;
  const dest = path.join(root, name); if (!dest.startsWith(root)) continue;
  if (type === '5') fs.mkdirSync(dest, { recursive: true }); else if (type === '0' || type === '\0') { fs.mkdirSync(path.dirname(dest), { recursive: true }); fs.writeFileSync(dest, body); }
}
const dataDir = process.env.NJW_DATA = process.env.NJW_DATA || path.join(os.tmpdir(), 'njw-data');
fs.mkdirSync(dataDir, { recursive: true });
const URL_ = (process.env.UPSTASH_REDIS_REST_URL || '').replace(/\/$/, ''), TOKEN = process.env.UPSTASH_REDIS_REST_TOKEN || '';
const FILES = ['players.json', 'world.json'], CHUNK = 400000, lastSent = {};
async function redis(cmds) {
  const r = await fetch(URL_ + '/pipeline', { method: 'POST', headers: { Authorization: 'Bearer ' + TOKEN, 'Content-Type': 'application/json' }, body: JSON.stringify(cmds) });
  if (!r.ok) throw new Error('redis HTTP ' + r.status); return r.json();
}
async function restore() {
  for (const f of FILES) {
    const m = (await redis([['GET', 'njw:' + f + ':meta']]))[0].result; if (!m) continue;
    const { n, t } = JSON.parse(m); const res = await redis(Array.from({ length: n }, (_, i) => ['GET', 'njw:' + f + ':' + t + ':' + i]));
    const b64 = res.map(x => x.result).join(''); if (res.some(x => x.result == null)) throw new Error('partes ausentes em ' + f);
    fs.writeFileSync(path.join(dataDir, f), zlib.gunzipSync(Buffer.from(b64, 'base64'))); lastSent[f] = fs.statSync(path.join(dataDir, f)).mtimeMs;
    console.log('[NJW] progresso restaurado:', f);
  }
}
let syncing = Promise.resolve();
function sync() {
  syncing = syncing.then(async () => {
    for (const f of FILES) {
      const p = path.join(dataDir, f); let st; try { st = fs.statSync(p); } catch (e) { continue; } if (lastSent[f] === st.mtimeMs) continue;
      const b64 = zlib.gzipSync(fs.readFileSync(p)).toString('base64'), t = Date.now().toString(36), n = Math.ceil(b64.length / CHUNK);
      for (let i = 0; i < n; i++) await redis([['SET', 'njw:' + f + ':' + t + ':' + i, b64.slice(i * CHUNK, (i + 1) * CHUNK)]]);
      await redis([['SET', 'njw:' + f + ':meta', JSON.stringify({ n, t })]]); lastSent[f] = st.mtimeMs;
    }
  }).catch(e => console.log('[NJW] falha ao salvar na nuvem:', e.message));
  return syncing;
}
(async () => {
  if (URL_ && TOKEN) {
    try { await restore(); } catch (e) { console.log('[NJW] não foi possível restaurar o progresso:', e.message); }
    const realExit = process.exit.bind(process); let leaving = false;
    process.exit = c => { if (leaving) return; leaving = true; Promise.race([sync(), new Promise(r => setTimeout(r, 4000))]).finally(() => realExit(c)); };
    setInterval(sync, 30000).unref(); console.log('[NJW] persistência na nuvem ativa');
  } else console.log('[NJW] sem UPSTASH_REDIS_REST_*: o progresso fica só no disco local (some ao reiniciar)');
  require(path.join(root, 'server', 'server.js'));
})();
